INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7282951, 1135221, 30490, '<td valign="top">This looked better in the thumbnail.... great use of irony, and if it had been technically better I would have rated it much higher.  This image needs to be straightened and less noise.</td>', 'This looked better in the thumbnail.... great use of irony, and if it had been technically better I would have rated it much higher.  This image needs to be straightened and less noise.', '2014-11-10 00:15:30.000000', NULL, 1),
(7282954, 1135221, 13891, '<td valign="top"><strike></strike></td>', '', '2014-11-10 00:23:50.000000', NULL, 1),
(7282955, 1135125, 13891, '<td valign="top"><strike></strike></td>', '', '2014-11-10 00:24:15.000000', NULL, 1),
(7282970, 1134610, 30861, '<td valign="top">I''m an HDR man myself, but this is just too cooked for my taste, the more so because "Waiting for Godot" is a bleak and unrelenting piece of work and, for me, it belongs in the darker end of the light spectrum, so to speak: I''d want the bleak-day-on-the-moors look here, nyself.<br/> <br/>Of course, that''s just me. It''s a heck of a location, a good POV, a dramatic sky, lots to like. If I felt the processing were more apt, it might have been an 8. As it is, a 7.</td>', 'I''m an HDR man myself, but this is just too cooked for my taste, the more so because "Waiting for Godot" is a bleak and unrelenting piece of work and, for me, it belongs in the darker end of the light spectrum, so to speak: I''d want the bleak-day-on-the-moors look here, nyself. Of course, that''s just me. It''s a heck of a location, a good POV, a dramatic sky, lots to like. If I felt the processing were more apt, it might have been an 8. As it is, a 7.', '2014-11-10 00:55:03.000000', NULL, 1),
(7282984, 1135110, 141826, '<td valign="top">10++</td>', '10++', '2014-11-10 01:55:24.000000', NULL, 1),
(7282985, 1135129, 141826, '<td valign="top">BEAUTIFUL!!!</td>', 'BEAUTIFUL!!!', '2014-11-10 02:04:41.000000', NULL, 1),
(7283026, 1134610, 159723, '<td valign="top">Not my kind of processing, but great composition!</td>', 'Not my kind of processing, but great composition!', '2014-11-10 05:54:00.000000', NULL, 1),
(7283036, 1135155, 159723, '<td valign="top">The gate is not doing it for me, but I like the b&amp;w conversion</td>', 'The gate is not doing it for me, but I like the b&w conversion', '2014-11-10 05:56:06.000000', NULL, 1),
(7283041, 1135223, 159723, '<td valign="top">Great shot! I visited Reykjavik this summer and found it really difficult to capture this impressive church. Well done! I bit more sharpness in the door and I would have scored it even higher.</td>', 'Great shot! I visited Reykjavik this summer and found it really difficult to capture this impressive church. Well done! I bit more sharpness in the door and I would have scored it even higher.', '2014-11-10 05:58:42.000000', NULL, 1),
(7283042, 1135110, 159723, '<td valign="top">Pity about those ugly fences, but great shot and for me perfect b&amp;w conversion.</td>', 'Pity about those ugly fences, but great shot and for me perfect b&w conversion.', '2014-11-10 06:03:08.000000', NULL, 1),
(7283050, 1135247, 159723, '<td valign="top">My favourite! Great colours and angles!</td>', 'My favourite! Great colours and angles!', '2014-11-10 06:07:04.000000', NULL, 1),
