(7285101, 1135144, 149964, '<td valign="top">Would have preferred to have seen less car and more church for the purposes of the challenge</td>', 'Would have preferred to have seen less car and more church for the purposes of the challenge', '2014-11-13 14:57:26.000000', NULL, 1),
