(7285380, 1135232, 13077, '<td valign="top">I like this. The tones are well suited for a cemetery scene, it''s composed very well too and overall very peaceful and classy.</td>', 'I like this. The tones are well suited for a cemetery scene, it''s composed very well too and overall very peaceful and classy.', '2014-11-15 00:10:54.000000', NULL, 1),
(7285381, 1135223, 13077, '<td valign="top">Impressive design.</td>', 'Impressive design.', '2014-11-15 00:11:17.000000', NULL, 1),
(7285382, 1135213, 13077, '<td valign="top">Very good light and exposure, and well composed.</td>', 'Very good light and exposure, and well composed.', '2014-11-15 00:11:35.000000', NULL, 1),
(7285383, 1135228, 13077, '<td valign="top">Nice - I like the position of the shadow in this one.</td>', 'Nice - I like the position of the shadow in this one.', '2014-11-15 00:12:02.000000', NULL, 1),
(7285384, 1135280, 13077, '<td valign="top">Excellent.</td>', 'Excellent.', '2014-11-15 00:12:28.000000', NULL, 1),
(7285385, 1135155, 13077, '<td valign="top">Beautiful place and beautiful photo to show it. One of my favorites so far.</td>', 'Beautiful place and beautiful photo to show it. One of my favorites so far.', '2014-11-15 00:12:59.000000', NULL, 1),
(7285386, 1135219, 13077, '<td valign="top">Fascinating building and sky. Very well composed and processed.</td>', 'Fascinating building and sky. Very well composed and processed.', '2014-11-15 00:13:27.000000', NULL, 1),
(7285387, 1135107, 13077, '<td valign="top">Good moody sort of photo, interesting concept. Visually speaking, it''s beautiful. Well done.</td>', 'Good moody sort of photo, interesting concept. Visually speaking, it''s beautiful. Well done.', '2014-11-15 00:14:11.000000', NULL, 1),
(7285388, 1135110, 13077, '<td valign="top">Awesome place and great job photographing it. I like how there''s no people in the scene, it''s just peaceful and serene under the softly overcast sky with some darkness at the top to hold it all in.</td>', 'Awesome place and great job photographing it. I like how there''s no people in the scene, it''s just peaceful and serene under the softly overcast sky with some darkness at the top to hold it all in.', '2014-11-15 00:15:23.000000', NULL, 1),
(7285389, 1135203, 13077, '<td valign="top">Interesting light and the composition is very good. Nicely done.</td>', 'Interesting light and the composition is very good. Nicely done.', '2014-11-15 00:15:49.000000', NULL, 1),
(7285390, 1135250, 13077, '<td valign="top">Not too fond about this one. Not commenting on the relevance to the challenge because my entry had nothing to do with it at all, but visually speaking I think this scene contained untapped potential and this composition fell short.</td>', 'Not too fond about this one. Not commenting on the relevance to the challenge because my entry had nothing to do with it at all, but visually speaking I think this scene contained untapped potential and this composition fell short.', '2014-11-15 00:16:46.000000', NULL, 1),
(7285391, 1135220, 13077, '<td valign="top">Being trampled underfoot, maybe.</td>', 'Being trampled underfoot, maybe.', '2014-11-15 00:17:23.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7285392, 1135087, 13077, '<td valign="top">Not crazy about the flare from the light at the left side of the frame here.</td>', 'Not crazy about the flare from the light at the left side of the frame here.', '2014-11-15 00:17:47.000000', NULL, 1),
(7285393, 1135225, 13077, '<td valign="top">I like the simplicity, but I think a better and more interesting composition could have been had from this scene.</td>', 'I like the simplicity, but I think a better and more interesting composition could have been had from this scene.', '2014-11-15 00:18:21.000000', NULL, 1),
(7285394, 1135283, 13077, '<td valign="top">It is certainly a church, but I think some of the weathered details might have made a fascinating photo. This strikes me as a google street view shot to be honest - I''m not saying it is, but that''s just the impression I get.</td>', 'It is certainly a church, but I think some of the weathered details might have made a fascinating photo. This strikes me as a google street view shot to be honest - I''m not saying it is, but that''s just the impression I get.', '2014-11-15 00:19:18.000000', NULL, 1),
(7285395, 1135261, 13077, '<td valign="top">.Well managed dynamic range here, and good composition, but I''m distracted by the blurred person at the right</td>', '.Well managed dynamic range here, and good composition, but I''m distracted by the blurred person at the right', '2014-11-15 00:20:54.000000', NULL, 1),
(7285396, 1135070, 13077, '<td valign="top">Fascinating reflection photo. The dark textures in those blocks are gorgeous, as are the windows and the split-up view through them.</td>', 'Fascinating reflection photo. The dark textures in those blocks are gorgeous, as are the windows and the split-up view through them.', '2014-11-15 00:21:27.000000', NULL, 1),
(7285397, 1135076, 13077, '<td valign="top">Good study of shapes and tones. Good artistic choice to use softness as well - some irony on several levels in this case that I will keep to myself.</td>', 'Good study of shapes and tones. Good artistic choice to use softness as well - some irony on several levels in this case that I will keep to myself.', '2014-11-15 00:25:44.000000', NULL, 1),
(7285398, 1135277, 13077, '<td valign="top">Well composed with the framing through the trees - not super crazy about the branch going across the window, but I wouldn''t have expected you to tear down the branch either. Good light too, with the shadows on the side of the church.</td>', 'Well composed with the framing through the trees - not super crazy about the branch going across the window, but I wouldn''t have expected you to tear down the branch either. Good light too, with the shadows on the side of the church.', '2014-11-15 00:26:39.000000', NULL, 1),
(7285399, 1135007, 13077, '<td valign="top">Very cool.</td>', 'Very cool.', '2014-11-15 00:31:47.000000', NULL, 1),
(7285400, 1134736, 13077, '<td valign="top">Nice - I like the inclusion of the people in front of the huge cathedral to give it scale.</td>', 'Nice - I like the inclusion of the people in front of the huge cathedral to give it scale.', '2014-11-15 00:32:16.000000', NULL, 1),
(7285401, 1135153, 13077, '<td valign="top">Simple but effective, nicely done.</td>', 'Simple but effective, nicely done.', '2014-11-15 00:32:26.000000', NULL, 1),
(7285402, 1135279, 13077, '<td valign="top">I''m guessing they are a religious type of band or something?</td>', 'I''m guessing they are a religious type of band or something?', '2014-11-15 00:32:52.000000', NULL, 1),
(7285403, 1135235, 13077, '<td valign="top">Nice use of the branches for framing, and beautiful light. Very good processing too.</td>', 'Nice use of the branches for framing, and beautiful light. Very good processing too.', '2014-11-15 00:33:09.000000', NULL, 1),
(7285404, 1135245, 13077, '<td valign="top">Super cool dramatic sky in this one. Well done processing.</td>', 'Super cool dramatic sky in this one. Well done processing.', '2014-11-15 00:33:28.000000', NULL, 1),
(7285405, 1135274, 13077, '<td valign="top">The street graffiti there is fascinating, I almost don''t want to look at the church...</td>', 'The street graffiti there is fascinating, I almost don''t want to look at the church...', '2014-11-15 00:34:03.000000', NULL, 1),
(7285406, 1135192, 13077, '<td valign="top">Has a sort of voyeuristic feel from looking at them out of the bushes... Not crazy about the hazy outline on the top of the church.</td>', 'Has a sort of voyeuristic feel from looking at them out of the bushes... Not crazy about the hazy outline on the top of the church.', '2014-11-15 00:34:42.000000', NULL, 1),
(7285407, 1135140, 13077, '<td valign="top">Nice - simple but attractive and timeless.</td>', 'Nice - simple but attractive and timeless.', '2014-11-15 00:34:56.000000', NULL, 1),
(7285408, 1135130, 13077, '<td valign="top">Simple and well composed.</td>', 'Simple and well composed.', '2014-11-15 00:35:18.000000', NULL, 1),
(7285410, 1135191, 13077, '<td valign="top">The textures here are interesting, and imagined as a 2 dimensional object the lines and shapes work together well too. At first, literal as our minds will tend to, there''s nothing particularly interesting about it, but viewed in the context of abstract shapes and patterns it''s quite beautiful.</td>', 'The textures here are interesting, and imagined as a 2 dimensional object the lines and shapes work together well too. At first, literal as our minds will tend to, there''s nothing particularly interesting about it, but viewed in the context of abstract shapes and patterns it''s quite beautiful.', '2014-11-15 00:37:50.000000', NULL, 1),
(7285411, 1135224, 13077, '<td valign="top">There seems to be a lot of noise reduction or something in the fine textures here - not crazy about the end result.</td>', 'There seems to be a lot of noise reduction or something in the fine textures here - not crazy about the end result.', '2014-11-15 00:38:19.000000', NULL, 1),
(7285413, 1134955, 13077, '<td valign="top">Interesting blend of colors, shapes and patterns here. Attractive composition.</td>', 'Interesting blend of colors, shapes and patterns here. Attractive composition.', '2014-11-15 00:39:03.000000', NULL, 1),
(7285414, 1135249, 13077, '<td valign="top">I actually like the composition, tones and sky, but it has the look of an over-zoomed phone camera shot or something. It''s a good perspective and works well for the scene - I like the effect of the church rising out of the cornfield.</td>', 'I actually like the composition, tones and sky, but it has the look of an over-zoomed phone camera shot or something. It''s a good perspective and works well for the scene - I like the effect of the church rising out of the cornfield.', '2014-11-15 00:40:14.000000', NULL, 1),
(7285415, 1135207, 13077, '<td valign="top">Beautiful place, hard to go wrong with a photo of a place like that.</td>', 'Beautiful place, hard to go wrong with a photo of a place like that.', '2014-11-15 00:40:46.000000', NULL, 1),
(7285416, 1135217, 13077, '<td valign="top">Fascinating looking place, curious as to where this is.</td>', 'Fascinating looking place, curious as to where this is.', '2014-11-15 00:40:59.000000', NULL, 1),
(7285417, 1135074, 13077, '<td valign="top">Drive faster, they''re trying to convert you!<br/> <br/>just kidding</td>', 'Drive faster, they''re trying to convert you! just kidding', '2014-11-15 00:41:26.000000', NULL, 1),
(7285418, 1135273, 13077, '<td valign="top">Very nice - simple. Dramatic and attractive.</td>', 'Very nice - simple. Dramatic and attractive.', '2014-11-15 00:42:17.000000', NULL, 1),
(7285419, 1135260, 13077, '<td valign="top">Well positioned and a nice sky for a backdrop.</td>', 'Well positioned and a nice sky for a backdrop.', '2014-11-15 00:42:44.000000', NULL, 1),
(7285420, 1135125, 13077, '<td valign="top">Nice looking place and beautiful light.</td>', 'Nice looking place and beautiful light.', '2014-11-15 00:43:12.000000', NULL, 1),
(7285421, 1135205, 13077, '<td valign="top">Well composed and processed, has a timeless feel but it makes me wonder if those big trees were saplings when the church was built, or maybe they didn''t even exist yet.</td>', 'Well composed and processed, has a timeless feel but it makes me wonder if those big trees were saplings when the church was built, or maybe they didn''t even exist yet.', '2014-11-15 00:44:04.000000', NULL, 1),
(7285422, 1135129, 13077, '<td valign="top">The scene is nice and has potential, but I think a visually better composition might have been found here.</td>', 'The scene is nice and has potential, but I think a visually better composition might have been found here.', '2014-11-15 00:45:08.000000', NULL, 1),
(7285423, 1135257, 13077, '<td valign="top">An interesting cross and nicely backlit green leaves here.</td>', 'An interesting cross and nicely backlit green leaves here.', '2014-11-15 00:45:44.000000', NULL, 1),
(7285424, 1134610, 13077, '<td valign="top">Looks like a nice place, but I don''t know about the over-the-top processing personally...<br/>Well composed though, and good light.</td>', 'Looks like a nice place, but I don''t know about the over-the-top processing personally...Well composed though, and good light.', '2014-11-15 00:46:32.000000', NULL, 1),
(7285425, 1135188, 13077, '<td valign="top">There''s something beautiful about this, and the lo-fi look works perfectly.</td>', 'There''s something beautiful about this, and the lo-fi look works perfectly.', '2014-11-15 00:46:55.000000', NULL, 1),
(7285426, 1135282, 13077, '<td valign="top">A well timed shot, but I wonder if any detail could have been had in the highlights?</td>', 'A well timed shot, but I wonder if any detail could have been had in the highlights?', '2014-11-15 00:47:27.000000', NULL, 1),
(7285427, 1135222, 13077, '<td valign="top">I like the vivid blue of the sky, but I think a more interesting composition could have been had here.</td>', 'I like the vivid blue of the sky, but I think a more interesting composition could have been had here.', '2014-11-15 00:47:53.000000', NULL, 1),
(7285428, 1134804, 13077, '<td valign="top">Not crazy about the visual dominance this tree on the right is exerting over the rest of the frame.</td>', 'Not crazy about the visual dominance this tree on the right is exerting over the rest of the frame.', '2014-11-15 00:48:19.000000', NULL, 1),
(7285429, 1135080, 13077, '<td valign="top">Nicely done. I can see your camera &amp; tripod though!</td>', 'Nicely done. I can see your camera & tripod though!', '2014-11-15 00:48:48.000000', NULL, 1),
(7285430, 1134953, 13077, '<td valign="top">Did anyone attend?</td>', 'Did anyone attend?', '2014-11-15 00:49:18.000000', NULL, 1),
(7285431, 1134944, 13077, '<td valign="top">Simple enough.<br/>I don''t know about the border though.</td>', 'Simple enough.I don''t know about the border though.', '2014-11-15 00:49:47.000000', NULL, 1),
(7285432, 1134984, 13077, '<td valign="top">Interesting visual tension you''ve created here by chopping the billboard''s words. I like the utility pole and its rendition of a cross as well.</td>', 'Interesting visual tension you''ve created here by chopping the billboard''s words. I like the utility pole and its rendition of a cross as well.', '2014-11-15 00:50:49.000000', NULL, 1),
(7285433, 1135194, 13077, '<td valign="top">LOL - takes almost as much money as a church from you too</td>', 'LOL - takes almost as much money as a church from you too', '2014-11-15 00:51:08.000000', NULL, 1),
(7285434, 1135086, 13077, '<td valign="top">nice dramatic sky and use of the fall colored foliage here.</td>', 'nice dramatic sky and use of the fall colored foliage here.', '2014-11-15 00:51:27.000000', NULL, 1),
